        logReq.onsuccess = () => {
          logReady = true;
          logRecord = logReq.result ?? logRecord;
          apply();
        };
        logReq.onerror = () => {
          logReady = true;
          apply();
        };
        return new Promise((resolve, reject) => {
          tx.oncomplete = () => resolve(count);
          tx.onerror = () => reject(tx.error);
          tx.onabort = () => reject(tx.error ?? new Error("API cost batch resolution aborted"));
        });
